import { readFileSync } from 'fs'

// Validate command line arguments
const args = process.argv.slice(2)
if (args.length !== 1 || !['rounds', 'tally'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}

const mode = args[0]

// Read stdin
let input = ''
try {
  input = readFileSync(0, 'utf-8')
} catch (e) {
  // Handle empty input
  input = ''
}

// Parse input
const lines = input.split('\n').slice(0, -1) // Drop trailing empty line from final newline

let candidates = null
let candidatesLineNum = null
const ballots = []
let lineNum = 0

for (const rawLine of lines) {
  lineNum++

  // Trim and ignore empty lines and comments
  const line = rawLine.trim()
  if (line === '' || line.startsWith('#')) {
    continue
  }

  // Split on whitespace runs
  const parts = line.split(/\s+/)
  const directive = parts[0]

  if (directive === 'candidates') {
    // Check if candidates already declared
    if (candidates !== null) {
      process.stderr.write(`error: line ${lineNum}: candidates must be declared once, before any ballot\n`)
      process.exit(2)
    }

    // Extract candidate names
    const names = parts.slice(1)
    if (names.length === 0) {
      process.stderr.write(`error: line ${lineNum}: expected candidates <name>...\n`)
      process.exit(2)
    }

    // Validate candidate names and check for duplicates
    const seen = new Set()
    for (const name of names) {
      if (!isValidName(name)) {
        process.stderr.write(`error: line ${lineNum}: invalid candidate name ${name}\n`)
        process.exit(2)
      }
      if (seen.has(name)) {
        process.stderr.write(`error: line ${lineNum}: candidate ${name} is declared twice\n`)
        process.exit(2)
      }
      seen.add(name)
    }

    candidates = names
    candidatesLineNum = lineNum
  } else if (directive === 'ballot') {
    // Check if candidates declared
    if (candidates === null) {
      process.stderr.write(`error: line ${lineNum}: candidates must be declared once, before any ballot\n`)
      process.exit(2)
    }

    // Parse ballot
    if (parts.length < 2) {
      process.stderr.write(`error: line ${lineNum}: expected ballot <count> <candidate>...\n`)
      process.exit(2)
    }

    const countStr = parts[1]
    const ballotCandidates = parts.slice(2)

    // Validate count
    if (!isPositiveInteger(countStr)) {
      process.stderr.write(`error: line ${lineNum}: count must be a positive integer\n`)
      process.exit(2)
    }

    const count = parseInt(countStr, 10)

    // Validate we have at least one candidate
    if (ballotCandidates.length === 0) {
      process.stderr.write(`error: line ${lineNum}: expected ballot <count> <candidate>...\n`)
      process.exit(2)
    }

    // Validate all candidates are declared
    const candidateSet = new Set(candidates)
    const seenInBallot = new Set()

    for (const candidate of ballotCandidates) {
      if (!candidateSet.has(candidate)) {
        process.stderr.write(`error: line ${lineNum}: unknown candidate ${candidate}\n`)
        process.exit(2)
      }
      if (seenInBallot.has(candidate)) {
        process.stderr.write(`error: line ${lineNum}: candidate ${candidate} is repeated\n`)
        process.exit(2)
      }
      seenInBallot.add(candidate)
    }

    ballots.push({ count, preferences: ballotCandidates })
  } else {
    process.stderr.write(`error: line ${lineNum}: unknown directive ${directive}\n`)
    process.exit(2)
  }
}

// Check if candidates were declared
if (candidates === null) {
  process.stderr.write('error: no candidates\n')
  process.exit(2)
}

// Run the election
const result = runElection(candidates, ballots, mode)
console.log(result)
process.exit(0)

// Helper functions

function isValidName(name) {
  return /^[A-Za-z0-9_-]+$/.test(name)
}

function isPositiveInteger(str) {
  // Must be decimal, no sign, no leading zero (unless it's just "0")
  if (str === '0') return false
  if (str.startsWith('0')) return false
  if (!/^\d+$/.test(str)) return false
  return true
}

function runElection(candidates, ballots, mode) {
  const output = []
  const rounds = []

  // Initialize continuing candidates and vote counts
  let continuing = new Set(candidates)
  let totalBallots = 0

  for (const ballot of ballots) {
    totalBallots += ballot.count
  }

  // Handle edge case: no ballots
  if (totalBallots === 0) {
    const counts = {}
    for (const candidate of candidates) {
      counts[candidate] = 0
    }
    if (mode === 'rounds') {
      output.push(formatRound(1, counts, 0))
    }
    output.push('no winner')
    return output.join('\n')
  }

  let roundNum = 0
  let winner = null

  while (true) {
    roundNum++

    // Count votes in this round
    const counts = {}
    let activeBallots = 0

    for (const candidate of candidates) {
      counts[candidate] = 0
    }

    for (const ballot of ballots) {
      // Find first continuing candidate
      let foundContinuing = false
      for (const candidate of ballot.preferences) {
        if (continuing.has(candidate)) {
          counts[candidate] += ballot.count
          activeBallots += ballot.count
          foundContinuing = true
          break
        }
      }
      // If not found, ballot is exhausted (contributes to exhausted count but not to any candidate)
    }

    const exhausted = totalBallots - activeBallots

    // Store this round's counts for tiebreaking later
    rounds.push({ counts: { ...counts }, active: activeBallots, exhausted })

    if (mode === 'rounds') {
      output.push(formatRound(roundNum, counts, exhausted))
    }

    // Check for winner
    if (activeBallots === 0) {
      // No winner
      winner = null
      break
    }

    for (const candidate of continuing) {
      if (counts[candidate] * 2 > activeBallots) {
        winner = candidate
        break
      }
    }

    if (winner) {
      break
    }

    // Eliminate candidate with fewest votes
    const eliminated = findCandidateToEliminate(counts, continuing, rounds)
    continuing.delete(eliminated)

    if (mode === 'rounds') {
      output.push(`eliminated ${eliminated}`)
    }
  }

