  const candidateList = Object.keys(counts).sort((a, b) => {
    const votesDiff = counts[b] - counts[a]
    if (votesDiff !== 0) return votesDiff
    return a.localeCompare(b)
  })

  const parts = candidateList.map(c => `${c}=${counts[c]}`)
  parts.push(`exhausted=${exhausted}`)

  return `round ${roundNum}: ${parts.join(' ')}`
}

function findCandidateToEliminate(counts, continuing, rounds) {
  // Find candidates with minimum votes in this round
  const continuing_array = Array.from(continuing)
  let minVotes = Infinity

  for (const candidate of continuing_array) {
    minVotes = Math.min(minVotes, counts[candidate])
  }

  let candidates_with_min = continuing_array.filter(c => counts[c] === minVotes)

  if (candidates_with_min.length === 1) {
    return candidates_with_min[0]
  }

  // Tiebreaker: compare across rounds from first to last
